TP.register({id:"lp7-gk",lp:7,grade:"K",mode:"curriculum",checks:6,nextGrade:"1st grade",build(E){const F=E.F;const HOUSE="cabin",TREE="tree",FLOWER="purpleFlower",SUNFLOWER="sunflower",CAT="cat",DUCK="duck",DOG="dog",BEE="bee",SUN="sun",SOUP="soup",BOOK="books",BOX="box",LEAF="leaf",SPROUT="sprout",BOOT="boot",EAR="ear",TALK="speak",HAND="hand",HANDS="hands";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const GARDEN="On the edge of our town there is a garden that everybody shares. Each family looks after one row. The rule is a simple one: you take care of your own row, and you also water the row next to yours whenever that neighbor is away. By the gate there is a little shed with tools in it. Anybody may borrow a tool, as long as it goes back clean. In the summer, when one row grows more beans than one family could ever eat, the extra beans go into a basket by the gate for whoever wants them.";const BEE_FACTS="A bee and a flower help each other, and neither one of them knows it. The flower makes a sweet drink called nectar, deep down inside it. A bee crawls in to drink, and while it is in there, a fine yellow dust called pollen sticks all over its fuzzy legs. Then the bee flies to the next flower and some of that dust rubs off. A flower needs pollen from another flower before it can make seeds. So the bee gets a meal, and the flower gets the help it needs, and the garden keeps growing.";const NAME_LETTERS=["F","a","P","g","C","h","W","j","Q","q"];const SOUND_LETTERS=["b","A","f","r","o","H","k","j","v","i"];const DISP="font-family:var(--font-display);font-weight:800";const WRITE_DIR="Draw and write on your paper. Hold it up when you finish.";const LINE_STYLE="font-size:2.2rem;line-height:1.9;margin:0 auto;width:fit-content";function wordGrid(ws){return`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:6px 0 10px">${ws.map(w=>`<div style="border:3px solid var(--line);border-radius:16px;text-align:center;padding:14px 6px;background:var(--surface);${DISP};font-size:clamp(2rem,6vw,3.4rem)">${w}</div>`).join("")}</div>`}const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",PINK="#F4899E",ROSE="#F6B3D0",PURPLE="#C9A6EC",PEACH="#F7C07A",CORALH="#EE8E86",BRASS="#D9A066",CREAM="#FBF1E4",GLASS="#E8F2F6",WOOD="#C08A5E",SKY="#FBD9E4",SKY_L="#FDEEF3",GRASS="#C6E8AE",GRASS_D="#A9D790",GRASS_E="#9BCC84",GRASS_E2="#86B86E",POND="#AFD9EE",POND_E="#79AFC9",FOAM="#FBFEFF",STEM="#7FC08A",LEAFA="#A8D49A",LEAFB="#BFE3A8",LEAFE="#4E7A46";function heartShape(x,y,s,c){const k=s/60,c0=c||PINK;return`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})"><path d="M0 20 C-25 3 -30 -13 -18 -21 C-9 -27 -2 -22 0 -16 C2 -22 9 -27 18 -21 C30 -13 25 3 0 20 Z" fill="${c0}" stroke="${INK}" stroke-width="2.6" stroke-linejoin="round"/>`+at(0,-5,.5,K_FACE(0,0,12,4))+`</g>`}const heartSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*.85)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a paper heart">${heartShape(w/2,w*.51,w*.92,c)}</svg>`;function heartFlower(x,y,s,c){s=s||1;return`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(s)})"><path d="M0 26 V0" fill="none" stroke="${STEM}" stroke-width="5" stroke-linecap="round"/><path d="M0 14 q-15 -9 -19 2 q14 8 19 -2 Z" fill="${LEAFA}" stroke="${LEAFE}" stroke-width="2.2" stroke-linejoin="round"/><path d="M0 22 q15 -9 19 2 q-14 8 -19 -2 Z" fill="${LEAFB}" stroke="${LEAFE}" stroke-width="2.2" stroke-linejoin="round"/>`+heartShape(0,-10,51,c)+`</g>`}function lab(x,y,t,sz,c){return`<text x="${x}" y="${y}" font-size="${sz||24}" font-family="Andika,sans-serif" font-weight="700" fill="${c||"var(--ink)"}" text-anchor="middle">${t}</text>`}function meadowPanel(w,h,base){let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;b+=`<g fill="${SKY_L}" opacity=".95"><ellipse cx="${n1(w*.18)}" cy="62" rx="52" ry="22"/><ellipse cx="${n1(w*.24)}" cy="52" rx="34" ry="17"/></g>`;b+=`<path d="M8 ${base-28} Q${n1(w*.32)} ${base-48} ${n1(w*.6)} ${base-30} T${w-8} ${base-38} V${h-8} H8 Z" fill="${GRASS}"/>`;b+=`<path d="M8 ${base-28} Q${n1(w*.32)} ${base-48} ${n1(w*.6)} ${base-30} T${w-8} ${base-38}" fill="none" stroke="${GRASS_E}" stroke-width="3.2" stroke-linecap="round"/>`;b+=`<path d="M8 ${base} Q${n1(w*.36)} ${base-18} ${n1(w*.66)} ${base-2} T${w-8} ${base-6} V${h-8} H8 Z" fill="${GRASS_D}"/>`;b+=`<path d="M8 ${base} Q${n1(w*.36)} ${base-18} ${n1(w*.66)} ${base-2} T${w-8} ${base-6}" fill="none" stroke="${GRASS_E2}" stroke-width="3.2" stroke-linecap="round"/>`;return b}const pondShape=(cx,cy,rx,ry)=>`<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${POND}" stroke="${POND_E}" stroke-width="3"/><path d="M${n1(cx-rx*.55)} ${cy-4} q${n1(rx*.28)} -7 ${n1(rx*.56)} 1" fill="none" stroke="${FOAM}" stroke-width="3" stroke-linecap="round" opacity=".95"/>`;function gateShape(x,baseY,w,h){const x0=x-w/2,x1=x+w/2;let b=`<rect x="${x0-6}" y="${baseY-h}" width="12" height="${h}" rx="6" fill="${WOOD}" stroke="${INK}" stroke-width="3.2"/>`;b+=`<rect x="${x1-6}" y="${baseY-h}" width="12" height="${h}" rx="6" fill="${WOOD}" stroke="${INK}" stroke-width="3.2"/>`;for(let i=0;i<3;i++)b+=`<rect x="${x0}" y="${baseY-h+12+i*Math.round((h-24)/3)}" width="${w}" height="8" rx="4" fill="#E0B47E" stroke="${INK}" stroke-width="2.4"/>`;return b}function gardenFig(){const w=620,h=336,base=226;let b=meadowPanel(w,h,base);b+=heartFlower(30,276,.6)+heartFlower(592,272,.55,PURPLE);b+=F.picXY(96,176,HOUSE,108)+F.picXY(228,172,TREE,92)+F.picXY(254,222,CAT,52);b+=gateShape(368,252,84,72)+F.picXY(368,232,DOG,56);b+=pondShape(520,254,72,26)+F.picXY(520,234,DUCK,58);b+=lab(96,316,"shed",22,"#4A332A")+lab(228,316,"tree",22,"#4A332A")+lab(368,316,"gate",22,"#4A332A")+lab(520,316,"pond",22,"#4A332A");return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A shared garden. A little shed is on the left, then a tree with a cat sitting under it, then a wooden gate with a small dog beside it, and on the right a pond with a duck on it.">${b}</svg>`}function linesFig(){const tagP=e=>`<span style="line-height:1" aria-hidden="true">${ic(e,40)}</span>`;const line=(a,t,b)=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:16px">${tagP(a)}<span style="${DISP};font-size:clamp(1.7rem,4.4vw,2.9rem);flex:1;text-align:left">${t}</span>${tagP(b)}</div>`;return`<div style="width:fit-content;margin:8px auto 10px;border:6px solid var(--sea);border-radius:16px;background:var(--surface);padding:12px 22px;display:grid;gap:10px">${line(BOOT,"We work in the garden.",SPROUT)}${line(SUN,"My row is wet.",DUCK)}</div><p class="small" style="text-align:center">The four pictures are a boot, a little sprout, the sun, and a duck.</p>`}function helpChart(){const rows=[[HANDS,"two hands"],[SOUP,"soup"],[BOOK,"a book"]];const right=["carry a heavy box","take to a sick friend","read to a little kid"];const cell=(pic,word)=>`<span style="display:inline-block;text-align:center;min-width:120px"><span style="display:block;line-height:1.1" aria-hidden="true">${ic(pic,48)}</span><span style="display:block;font-family:var(--font-display);font-weight:700;font-size:1.3rem">${word}</span></span>`;const words=t=>`<span style="display:inline-block;max-width:190px;font-family:var(--font-display);font-weight:700;font-size:1.25rem;text-align:left">${t}</span>`;return`<div class="figure" style="gap:16px;flex-direction:column" role="img" aria-label="Picture chart: two hands carry a heavy box, soup is taken to a sick friend, a book is read to a little kid">`+rows.map((r,i)=>`<div style="display:flex;align-items:center;gap:10px;border:3px solid var(--line);border-radius:18px;padding:10px 16px;background:var(--surface)">${cell(r[0],r[1])}<span style="font-size:2rem;font-weight:800;color:var(--sea)" aria-hidden="true">&#8594;</span>${words(right[i])}</div>`).join("")+`</div>`}function heartRow(n){const w=620,h=150,x0=40,x1=w-40,sag=22,ry=x=>{const t=(x-x0)/(x1-x0);return 44+4*sag*t*(1-t)};let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;b+=`<path d="M${x0} 44 Q${(x0+x1)/2} ${44+2*sag} ${x1} 44" fill="none" stroke="${BRASS}" stroke-width="5" stroke-linecap="round"/>`;const cols=[PINK,ROSE,PURPLE,PEACH,CORALH];for(let i=0;i<n;i++){const x=x0+(i+.5)*(x1-x0)/n;b+=heartShape(x,ry(x)+34,48,cols[i%5])}return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A string across the garden with ${n} paper hearts hanging from it">${b}</svg>`}function jarSvg(n,w){w=w||150;const H=Math.round(w*180/220);const sc=w/300,gl="M80 76 h140 q10 0 10 12 v96 q0 14 -14 14 H84 q-14 0 -14 -14 V88 q0 -12 10 -12 Z";const cols=[PINK,ROSE,PURPLE,PEACH,CORALH];let h="";for(let k=0;k<n;k++)h+=heartShape(106+k%4*34+Math.floor(k/4)%2*17,170-Math.floor(k/4)*34,40,cols[k%5]);return`<svg viewBox="40 40 220 180" width="${w}" height="${H}" style="vertical-align:middle" role="img" aria-label="A glass jar with ${n} paper hearts in it"><rect x="70" y="50" width="160" height="24" rx="11" fill="${BRASS}" stroke="${INK}" stroke-width="4"/><path d="${gl}" fill="${GLASS}" opacity=".7"/>${h}<path d="${gl}" fill="none" stroke="${INK}" stroke-width="4.5" stroke-linejoin="round"/><path d="M98 96 V176" fill="none" stroke="#FFFFFF" stroke-width="5" stroke-linecap="round" opacity=".55"/></svg>`}function basketsFig(n){const w=620,h=240;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const basket=(x,y)=>`<path d="M${x-54} ${y-44} H${x+54} L${x+40} ${y} H${x-40} Z" fill="${BRASS}" stroke="${INK}" stroke-width="3.4" stroke-linejoin="round"/><path d="M${x-46} ${y-26} H${x+46} M${x-40} ${y-12} H${x+40}" stroke="#C89A64" stroke-width="3.4" stroke-linecap="round"/><rect x="${x-60}" y="${y-54}" width="120" height="16" rx="8" fill="#E0B47E" stroke="${INK}" stroke-width="3.2"/>`;b+=basket(96,160)+basket(228,160);b+=lab(162,196,"two baskets",22);const cols=[PEACH,PINK];for(let i=0;i<n;i++){const x=330+i%5*54,y=76+Math.floor(i/5)*72;b+=heartShape(x,y,48,cols[Math.floor(i/5)%2])}b+=lab(438,196,"the hearts",22);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="Two empty baskets on the left, and ${n} paper hearts waiting beside them">${b}</svg>`}function bookFig(){return`<p class="passage" style="${LINE_STYLE}">I see a pup.<br>The pup is sad.<br>I can help.<br>Now the pup is glad.<br>Now he can play.<br>We run and run.<br>The pup can jump.<br>I like my pup.</p><div class="figure" style="gap:14px" aria-hidden="true">${ic(DOG,48)}${ic(HAND,48)}${heartSvg(46,PINK)}</div><p class="small">Glad means happy.</p>`}function beeFig(){const w=560,h=200;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=F.picXY(110,130,SUNFLOWER,110)+F.picXY(450,130,FLOWER,110);b+=`<path d="M186 78 q92 -46 184 0" fill="none" stroke="var(--sea)" stroke-width="5" stroke-linecap="round" stroke-dasharray="11 9"/>`;b+=`<path d="M370 78 l-13 -10 v20 Z" fill="var(--sea)"/>`;b+=F.picXY(278,50,BEE,66);return`<svg viewBox="0 0 ${w} ${h}" width="540" role="img" aria-label="A sunflower on the left and another flower on the right, with a bee flying along a dotted path from one to the other.">${b}</svg>`}function unitFig(){const u=46,y1=56,y2=150;let s=`<svg viewBox="0 0 420 212" width="400" role="img" aria-label="A garden row above five blocks laid end to end, and a trowel above three blocks laid end to end.">`;s+=`<path d="M40 ${y1-8} h${5*u}" stroke="${STEM}" stroke-width="9" stroke-linecap="round" fill="none"/>`;for(let i=0;i<5;i++)s+=`<rect x="${40+i*u}" y="${y1+4}" width="${u}" height="26" fill="${PEACH}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(312,y1+24,"row",24);s+=`<path d="M40 ${y2-14} h${3*u}" stroke="${BRASS}" stroke-width="9" stroke-linecap="round" fill="none"/>`;for(let i=0;i<3;i++)s+=`<rect x="${40+i*u}" y="${y2}" width="${u}" height="26" fill="${PEACH}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(232,y2+20,"trowel",24);s+=`<text x="40" y="202" font-size="20" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+"</svg>"}const boxBg=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;function heartTray(n){const w=560,per=5,rows=Math.ceil(n/per),h=rows*86+36;let b=boxBg(w,h);const cols=[PINK,ROSE,PURPLE,PEACH,CORALH];for(let i=0;i<n;i++)b+=heartShape(78+i%per*100,60+Math.floor(i/per)*86,62,cols[i%5]);return`<svg viewBox="0 0 ${w} ${h}" width="540" role="img" aria-label="A tray holding ${n} paper hearts">${b}</svg>`}function cmpBox(t,eA,nA,cellA,eB,nB,cellB,alt){const w=680,h=182;let b=boxBg(w,h)+`<circle cx="42" cy="44" r="20" fill="var(--sea-soft)" stroke="var(--line)" stroke-width="2"/><text x="42" y="45" font-size="22" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${t}</text>`;for(let i=0;i<nA;i++){const x=90+i*cellA+cellA/2;b+=eA==="HEART"?heartShape(x,56,54):F.picXY(x,56,eA,58)}for(let i=0;i<nB;i++){const x=90+i*cellB+cellB/2;b+=eB==="HEART"?heartShape(x,136,54):F.picXY(x,136,eB,58)}return`<svg viewBox="0 0 ${w} ${h}" width="620" role="img" aria-label="${alt}">${b}</svg>`}function tenAndMore(extra){const w=680,h=190;let b=boxBg(w,h);b+=`<rect x="26" y="34" width="330" height="118" rx="16" fill="none" stroke="${BRASS}" stroke-width="5"/>`;b+=lab(191,176,"ten",24,"var(--muted)");for(let i=0;i<10;i++)b+=heartShape(58+i%5*66,66+Math.floor(i/5)*56,50,PINK);for(let i=0;i<extra;i++)b+=heartShape(420+i%3*76,70+Math.floor(i/3)*56,50,PURPLE);b+=lab(496,176,"some more",24,"var(--muted)");return`<svg viewBox="0 0 ${w} ${h}" width="620" role="img" aria-label="A marked box holding 10 pink hearts, and ${extra} purple hearts loose beside it">${b}</svg>`}function comparePairs(){const w=680,h=300,x0=116;let b=boxBg(w,h)+`<path d="M${x0-10} 30 V112" stroke="var(--line)" stroke-width="4" stroke-linecap="round"/>`;b+=lab(60,54,"A",26)+`<rect x="${x0}" y="40" width="300" height="22" rx="10" fill="${PINK}" stroke="${INK}" stroke-width="3"/>`;b+=lab(60,98,"B",26)+`<rect x="${x0}" y="84" width="150" height="22" rx="10" fill="${PURPLE}" stroke="${INK}" stroke-width="3"/>`;b+=`<path d="M26 258 H${w-26}" stroke="var(--line)" stroke-width="4" stroke-linecap="round"/>`;b+=F.picXY(210,196,SUNFLOWER,124)+lab(210,284,"C",26);b+=F.picXY(470,220,SUNFLOWER,76)+lab(470,284,"D",26);return`<svg viewBox="0 0 ${w} ${h}" width="620" role="img" aria-label="At the top, ribbon A and ribbon B start at the same edge and ribbon A reaches further. At the bottom, sunflower C and sunflower D stand on the same line and sunflower C is taller.">${b}</svg>`}const MIX=["HEART",LEAF,SPROUT,"HEART","HEART",LEAF,SPROUT,"HEART",LEAF,"HEART",SPROUT,LEAF,"HEART"];function mixTray(){const w=680,per=7,rows=Math.ceil(MIX.length/per),h=rows*96+30;let b=boxBg(w,h);MIX.forEach((e,i)=>{const x=60+i%per*92,y=62+Math.floor(i/per)*96;b+=e==="HEART"?heartShape(x,y,62):F.picXY(x,y,e,66)});return`<svg viewBox="0 0 ${w} ${h}" width="620" role="img" aria-label="A tray with 6 paper hearts, 4 leaves and 3 sprouts all mixed together">${b}</svg>`}function shapeShedFig(){const w=680,h=300,st=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;let b=boxBg(w,h)+`<path d="M30 250 H${w-30}" stroke="var(--line)" stroke-width="5" stroke-linecap="round"/>`;b+=`<polygon points="203,46 300,120 106,120" fill="${PURPLE}" ${st}/>`;b+=`<rect x="138" y="120" width="130" height="130" fill="${PEACH}" ${st}/>`;b+=`<circle cx="400" cy="214" r="36" fill="${ROSE}" ${st}/>`;b+=`<rect x="470" y="170" width="170" height="44" fill="${GRASS_D}" ${st}/>`;b+=lab(203,278,"shed",24,"var(--muted)")+lab(400,278,"stone",24,"var(--muted)")+lab(555,278,"bench",24,"var(--muted)");return`<svg viewBox="0 0 ${w} ${h}" width="620" role="img" aria-label="A shed drawn as a purple triangle roof sitting on a peach square wall, a round pink stepping stone beside the shed, and a long green rectangle bench to the right of the stone.">${b}</svg>`}function flatSolidFig(){const w=800,h=240,st=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;let b=boxBg(w,h);const num=(x,t)=>lab(x,214,t,26,"var(--muted)");b+=`<circle cx="80" cy="106" r="46" fill="${ROSE}" ${st}/>`+num(80,"1");b+=`<ellipse cx="208" cy="158" rx="44" ry="11" fill="${INK}" opacity=".18"/><circle cx="208" cy="106" r="46" fill="${PEACH}" ${st}/><path d="M180 82 q20 -16 42 -8" fill="none" stroke="#FFFFFF" stroke-width="7" stroke-linecap="round" opacity=".6"/>`+num(208,"2");b+=`<rect x="314" y="60" width="92" height="92" fill="${PURPLE}" ${st}/>`+num(360,"3");b+=`<rect x="476" y="72" width="68" height="80" fill="${PINK}" ${st}/><polygon points="476,72 508,44 576,44 544,72" fill="${ROSE}" ${st}/><polygon points="544,72 576,44 576,124 544,152" fill="${CORALH}" ${st}/>`+num(524,"4");b+=`<polygon points="664,58 710,152 618,152" fill="${GRASS_D}" ${st}/>`+num(664,"5");b+=`<path d="M732 70 v68 a28 13 0 0 0 56 0 V70 Z" fill="${BRASS}" ${st}/><ellipse cx="760" cy="70" rx="28" ry="13" fill="${PEACH}" ${st}/>`+num(760,"6");return`<svg viewBox="0 0 ${w} ${h}" width="740" role="img" aria-label="Six things in a row. 1 is a flat pink circle, 2 is a round ball with a shine on it, 3 is a flat purple square, 4 is a box shaped like a cube, 5 is a flat green triangle, and 6 is a can shape.">${b}</svg>`}const STOPS=[{id:1,title:"Heart Tag Letters",short:"Tag Letters",parts:[{title:"Name the Letter",std:["RF.K.1"],kind:"words",full:E.alphabet(),words:NAME_LETTERS,unit:"Letter",n:10,dur:45,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters, including look-alike letters",key:["The student says the name of each letter: F, a, P, g, C, h, W, j, Q, q. Count a letter correct when the name is right. Sounds are not needed here.","Watch the look-alike pair P and q, which are the third card and the last card, and the pair g and q. Capital Q and lowercase q are the last two cards, so you can hear whether the student knows both shapes of the same letter. Write down any letters that were missed or mixed up."]},{title:"Two Lines",std:["RF.K.1"],n:3,dur:35,dir:"Look at the two lines. Answer out loud.",desc:"print concepts (counting words and letters)",html:()=>linesFig(),key:["Ask: How many words are in the top line? (5)","Ask: How many words are in the bottom line? (4)","Ask: Look at the first word in the bottom line. How many letters does it have? (2, the word My)"]}]},{id:2,title:"Count the Garden Row",short:"Count",parts:[{title:"Down the Row",std:["K.CC.A.1"],n:3,label:"checks met",dur:75,dir:"Count out loud. Start at 1. Go as high as you can.",desc:"counting out loud by ones",html:()=>`<p class="big" style="text-align:center">The garden club hangs a paper heart on the string for every kind thing somebody does. Count out loud as the hearts go up.</p><div class="figure">${heartRow(9)}</div>`,key:["Say: Start at 1 and count as high as you can. Check: counts 1 to 20 in order with no skips.","Keeps going from 20 to 40 and gets across each new ten (29 to 30, 39 to 40).","Counts past 50. Stop the student at 100. Write the highest number said before a mistake. The end of year goal is 100."]},{title:"Ten to a String",std:["K.CC.A.1"],n:2,label:"checks met",dur:45,dir:"Count by tens out loud.",desc:"counting by tens",html:()=>`<div class="figure">${heartSvg(70,PINK)}${heartSvg(70,PURPLE)}</div><p class="big" style="text-align:center">Each string holds 10 paper hearts. Count by tens to 100.</p>`,key:["Say: Count the hearts by tens as each string goes up. Check: says 10, 20, 30, 40, 50 with no help.","Keeps going: 60, 70, 80, 90, 100. Write the last number said in order."]}]},{id:3,title:"Garden Sounds",short:"Sounds",parts:[{title:"Rhyme and Clap",std:["RF.K.2"],n:6,dur:60,dir:"Listen to your teacher. Answer out loud.",desc:"hearing rhymes, making a rhyme, and clapping syllables",html:()=>`<div class="figure">${F.pic(EAR)}${F.pic(HANDS)}</div><p class="small" style="text-align:center">A row is a long line of plants in a garden.</p>`,key:["Ask: Do share and care rhyme? (yes)","Ask: Do kind and friend rhyme? (no)","Ask: Which word does not rhyme: row, grow, help? (help)","Say: Tell me a word that rhymes with seed. (feed, need, weed, read, bead. Silly words count.)","Say: Clap the parts in garden. (2 claps: gar-den)","Say: Clap the parts in butterfly. (3 claps: but-ter-fly)"]},{title:"Put It Together",std:["RF.K.2"],n:6,dur:60,dir:"Listen to your teacher. Answer out loud.",desc:"blending spoken sounds and saying the first, last, and all sounds in a word",html:()=>`<div class="figure">${F.pic(TALK)}${F.pic(BEE)}</div>`,key:["Say: Put these sounds together: /h/ /e/ /l/ /p/. (help)","Say: Put these sounds together: /s/ /ee/ /d/. (seed)","Ask: What is the first sound in gate? (/g/. The sound, not the letter name.)","Ask: What is the first sound in kind? (/k/)","Ask: What is the last sound in bug? (/g/)","Say: Tell me every sound in map. (/m/ /a/ /p/, three sounds)"]}]},{id:4,title:"Mo and Pip",short:"Mo Story",parts:[{std:["RL.K.1"],n:4,dur:90,dir:"Listen while your teacher reads the lines. Then answer out loud.",desc:"asking and answering questions about key details in a story read aloud to the student",html:()=>`<div class="figure" aria-hidden="true">${ic(SOUP,72)}${heartSvg(60,PINK)}</div><p class="passage" style="${LINE_STYLE}">Mo has a pot of soup.<br>Pip has no soup.<br>Mo gives Pip a cup.<br>Now they both eat.</p><p class="small">A pot holds the soup. You cook in a pot.</p>`,key:["Read the four lines on the screen out loud to the student two times. Point under each word as you read. The student does not read them. Ask: What does Mo have? (a pot of soup)","Ask: Who has no soup? (Pip)","Ask: What does Mo give Pip? (a cup)","Say: Now you ask me a question about Mo and Pip. Start with What or Who. (asks a real question about the lines, such as: What kind of soup is it?)"]}]},{id:5,title:"Hearts in the Jar",short:"Add It",parts:[{std:["K.OA.A.2"],n:5,dur:110,dir:"Listen to each story. You can draw on your paper. Say your answer out loud.",desc:"addition and subtraction word problems within 10, with drawings",html:()=>`<div class="figure">${jarSvg(6,190)}</div><p class="small" style="text-align:center">You can draw a circle for each heart on your paper, then count or cross out.</p>`,key:["Say: There are 3 paper hearts in the jar. Four more kind things happen, so 4 more hearts go in. How many hearts are in the jar now? (7. 3 + 4 = 7)","Say: 9 flowers were in the row. A friend picked 2 of them for her grandma. How many flowers are still in the row? (7. 9 - 2 = 7)","Say: 5 kids were raking leaves. Then 3 more kids came to help. How many kids are raking now? (8. 5 + 3 = 8)","Say: There were 10 muffins on the tray. The club gave 6 of them away. How many muffins are left? (4. 10 - 6 = 4)","Say: 2 birds were at the feeder. 6 more flew in. How many birds in all? (8. 2 + 6 = 8)","Drawing, fingers, or counters all count. Note whether the student counted every one from 1 or counted on from the bigger number."]}]},{id:6,title:"Two Baskets",short:"Break It",parts:[{std:["K.OA.A.3"],n:5,dur:95,dir:"Look at the hearts. Put some in each basket. Answer out loud.",desc:"breaking numbers up to 10 into two parts in more than one way",fig:()=>F.row(basketsFig(6)),fig2:()=>F.row(basketsFig(9)),qs:["Look at the first picture. There are 6 hearts and 2 baskets. Say one way to put them in the two baskets. Say it like this: ____ and ____ makes 6.","Now tell me a different way to make 6.","Look at the second picture. Count the hearts there. How many?","Say one way to put those hearts in the two baskets.","Now tell me a different way to make that same number."],key:["Any true pair for 6: 5 and 1, 4 and 2, 3 and 3, 2 and 4, 1 and 5, 6 and 0. The student has to say both parts.","A different true pair for 6 than the first one. Saying the same pair backwards (4 and 2, then 2 and 4) counts as different only if the student points to which basket each part goes in.","9 hearts","Any true pair for 9: 8 and 1, 7 and 2, 6 and 3, 5 and 4, and so on.","A second, different true pair for 9. If the student is stuck, say: You put 5 in this basket. How many are left for the other one? and count with them.","Writing it as 6 = 4 + 2 is a bonus, not a requirement. Saying the two parts out loud is enough at this grade."]}]},{id:7,title:"Garden Words",short:"Garden Words",parts:[{title:"Letter Sounds",std:["RF.K.3"],kind:"words",words:SOUND_LETTERS,unit:"Letter",n:10,dur:45,dir:"Say the sound each letter makes.",desc:"saying the sounds of letters",key:["The student says the most common sound for each letter: b /b/, A as in apple, f /f/, r /r/, o as in ox, H /h/, k /k/, j /j/, v /v/, i as in it. The letter name is not needed here.","The long sound for A, o or i is also fine. Write down any sounds that were missed."]},{title:"Kind Words",std:["RF.K.3"],n:9,dur:60,dir:"Read each word out loud.",desc:"reading high-frequency words and short vowel words",html:()=>wordGrid(["see","my","you","and","come","bud","hug","jam","fit"]),key:["High-frequency words the student should know by sight: see, my, you, and, come","Sounds out or reads: bud, hug, jam, fit","Score is the number of words read correctly out of 9. Write down which ones were missed."]}]},{id:8,title:"Listen to the Garden Club",short:"Listen",parts:[{std:["SL.K.2"],n:5,dur:75,dir:"Put your eyes on your teacher and listen. Then answer out loud.",desc:"answering questions about key details in a text read aloud and asking for help",html:()=>`<div class="figure">${F.pic(EAR)}${heartSvg(74,ROSE)}</div><p class="big" style="text-align:center">Listening time. Your teacher will read you a report about the garden everybody shares.</p>`,read:GARDEN,key:["Ask: How many rows does each family look after? (one row)","Ask: When do you water the row next to yours? (when that neighbor is away)","Ask: What is in the little shed by the gate? (tools)","Ask: What do you have to do with a tool you borrow? (put it back clean)","Say: Pretend you missed one part. What can you say to me? (asks for help, such as: Can you read that part again? or What is a row?)"]}]},{id:9,title:"Little Kind Book",short:"Kind Book",parts:[{std:["RF.K.4"],n:32,label:"words read correctly",dur:60,dir:"Point to each word and read it out loud.",desc:"reading a short emergent-reader book with purpose and understanding",html:()=>bookFig(),key:["Count the words the student reads correctly, out of 32, and enter the number in the box. A word the student fixes without help counts. Write down the words that were missed.","Points or tracks under each word, left to right and top to bottom","Reads most of the words correctly, including the sight words I, see, a, the, is, can. No picture words: pup, sad, glad, help and jump are all sound-out words","Ask: What is this little book about? (helping a sad pup, or a pup that feels better)"]}]},{id:10,title:"Bees and Flowers",short:"Bees",parts:[{std:["RI.K.1"],n:6,dur:90,dir:"Listen while your teacher reads the lines. Then answer out loud.",desc:"asking and answering questions about key details in an informational text about bees and flowers",html:()=>`<div class="figure">${beeFig()}</div><p class="passage" style="${LINE_STYLE}">A bee can help a flower.<br>The bee gets food.<br>The flower gets help.<br>Bees go from flower to flower.<br>Then the flower can make seeds.<br>The bee helps the flower.<br>The flower helps the bee.</p>`,read:BEE_FACTS,key:["Read the six lines on the screen out loud to the student two times. Point under each word as you read. The student does not read them. Ask: Who can help a flower? (a bee. Line 1.)","Ask: What does the bee get? (food. Line 2.)","Ask: What does the flower get? (help. Line 3.)","Ask: Where do bees go? (from flower to flower. Line 4.)","Ask: What can the flower make then? (seeds. Line 5.)","Say: Ask me a question about bees. Start with What or Where. (asks a real question about bees or flowers)","All six scored items come from the lines on the screen. After you score them you may read the longer bee text aloud for interest. It is not scored here."]}]},{id:11,title:"Garden Talk",short:"Talk",parts:[{std:["L.K.1"],n:5,dur:75,dir:"Look at the picture. Listen to your teacher. Say your answer out loud.",desc:"spoken grammar items (plural nouns, question words, position words in complete sentences)",html:()=>`<div class="figure">${gardenFig()}</div>`,key:["Say: One heart, two ____. (hearts)","Say: One bush, two ____. (bushes)","Say: Ask me a question that starts with Who. (asks a who question)","Say: Look at the picture. Where is the cat? Tell me in a whole sentence. (a complete sentence with under, such as: The cat is under the tree.)","Say: Where is the duck? Tell me in a whole sentence. (a complete sentence with on or in, such as: The duck is on the pond.)"]}]},{id:12,title:"Kindness Notebook",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Rake or Wash",icon:"💬",hint:"Draw it and tell what you think"},std:["W.K.1"],n:3,label:"checks met",dur:150,dir:WRITE_DIR,desc:"a draw-and-write opinion piece about which job is the better way to help",html:()=>`<div class="figure">${ic(LEAF,60)}${ic(SOUP,60)}</div><p class="big">Somebody needs a hand today. Would you rather rake the leaves in the yard, or wash the dishes after dinner? Draw the one you pick. Write or tell what you think and why.</p>`,key:["Tells the reader what the choice is about: raking the leaves or washing the dishes (W.K.1)","States an opinion, which one the student would pick. Drawing, telling, or writing all count (W.K.1)","Gives a reason or a detail for the pick, such as: I like being outside, or It is faster (W.K.1)","Only the challenge the student picks gets rated here. If this grade level's pacing sheet lists more than one of W.K.1, W.K.2 and W.K.3 for your curriculum, the other prompt works as a follow-up on paper another day, and the record sheet shows the unpicked one as unrated."]},{wk:"facts",alt:{group:"write",label:"Garden Facts",icon:"📖",hint:"Draw it and tell one true thing"},std:["W.K.2"],n:3,label:"checks met",dur:150,dir:WRITE_DIR,desc:"a draw-and-write informative piece about a bee, a dog, or a garden",html:()=>`<div class="figure">${ic(BEE,56)}${ic(DOG,56)}${ic(SUNFLOWER,56)}</div><p class="big">Pick one: a bee, a dog, or a garden. Draw it. Write its name. Then write or tell one true thing about it.</p><p class="small">A bee is an insect. It lands on flowers.</p>`,key:["Names what the drawing and writing are about: a bee, a dog, or a garden. The student may say it, label the picture, or write a letter or word for it (W.K.2)","Gives at least one piece of true information about it, such as: A bee lands on flowers. A dog likes to run. A garden needs water (W.K.2)","Uses drawing, telling, or writing (any mix) to get the information across (W.K.2)","Only the challenge the student picks gets rated here. If this grade level's pacing sheet lists more than one of W.K.1, W.K.2 and W.K.3 for your curriculum, the other prompt works as a follow-up on paper another day, and the record sheet shows the unpicked one as unrated."]},{wk:"story",alt:{group:"write",label:"Somebody Helped Me",icon:"✏",hint:"Draw and tell what happened"},std:["W.K.3"],n:4,label:"checks met",dur:150,dir:WRITE_DIR,desc:"a draw-and-write story about a time somebody helped, told in order with a reaction",html:()=>`<div class="figure">${ic(HAND,56)}${heartSvg(52,PINK)}${ic(HANDS,56)}</div><p class="big">Think of a time somebody helped you, or a time you helped somebody. Draw what happened. Then tell what happened first and what happened next. Tell how you felt.</p>`,key:["Tells about one real thing that happened, not a list of facts (W.K.3)","Tells two parts, a first and a next, in the order they happened (W.K.3)","Gives at least one detail about it, such as where it was or who was there (W.K.3)","Reacts to what happened, such as: It was nice, or I was glad, or I said thank you (W.K.3)","Only the challenge the student picks gets rated here. If this grade level's pacing sheet lists more than one of W.K.1, W.K.2 and W.K.3 for your curriculum, the other prompt works as a follow-up on paper another day, and the record sheet shows the unpicked one as unrated."]}]},{id:13,title:"The Helping Chart",short:"The Chart",parts:[{std:["W.K.8"],dur:60,dir:"Look at the chart. Answer out loud.",desc:"answering questions from a picture chart and from experience",fig:()=>helpChart(),qs:["Look at the chart. What do you use to carry a heavy box?","Look at the chart. What can you take to a sick friend?","Look at the chart. What can you read to a little kid?","Think about yesterday. What is one kind thing somebody did for you?"],key:["Two hands. Uses the chart to answer.","Soup. Uses the chart to answer.","A book. Uses the chart to answer.","Names one real thing, such as my brother shared his snack, or my mom tied my shoe. Recalls it from experience."]}]},{id:14,title:"Tell Me More",short:"Tell More",parts:[{std:["SL.K.4"],n:3,label:"checks met",dur:60,dir:"Tell your teacher out loud. Use lots of details.",desc:"describing a familiar thing you do, with details",html:()=>`<div class="figure">${F.pic(BOX)}${F.pic(SOUP)}${F.pic(BOOT)}</div><p class="big" style="text-align:center">Tell me about one job you do to help at home.</p>`,key:["Names the job and tells something about it","Adds a detail when you ask: Where do you do it?","Adds another detail when you ask: Who helps you, and what is the hard part?"]}]},{id:15,title:"How Many in the Tray",short:"How Many",parts:[{title:"Count and Tell",std:["K.CC.B.4"],n:3,dur:60,dir:"Count the hearts. Then answer out loud.",desc:"counting objects one by one and saying how many there are in all",fig:()=>F.row(heartTray(8)),key:["Say: The club cut these paper hearts for the jar. Count them and tell me how many. (8. One number word for each heart, with no skips and no double counts.)","Say it again a different way: So how many hearts are in the tray? (8, said straight back. Having to count all over again is the thing to write down.)","Say: Now I drop one more heart in the tray. How many will there be? (9. Look for 9 without counting the whole tray again, because 9 comes right after 8.)"]},{title:"Greater, Less, or Equal",std:["K.CC.C.6"],n:3,dur:60,dir:"Look at the two boxes. Count, then answer out loud.",fig:()=>F.row(cmpBox(1,"HEART",9,58,LEAF,6,88,"Box 1: a row of 9 paper hearts above a row of 6 leaves that are spread further apart")),fig2:()=>F.row(cmpBox(2,FLOWER,7,76,BEE,7,76,"Box 2: a row of 7 flowers above a row of 7 bees")),desc:"deciding whether one group is greater than, less than, or equal to another",key:["Box 1. Ask: Which group is greater, the hearts or the leaves? How do you know? (The hearts. 9 hearts and 6 leaves. The leaves are spread out, so the two rows look about the same length. Look for counting or for matching one leaf to one heart.)","Box 1 again. Ask: So which group is less? (The leaves. 6 is less than 9.)","Box 2. Ask: Are there more flowers, more bees, or are the two groups equal? (Equal. 7 flowers and 7 bees.)","Listen for the words greater, less, or equal. If the student says more and fewer, that counts, but ask once: Can you say it with greater or less?"]}]},{id:16,title:"Ten and Some More",short:"Teens",parts:[{std:["K.NBT.A.1"],n:3,dur:65,dir:"Look at the hearts. Answer out loud.",desc:"seeing a teen number as ten ones and some more ones",fig:()=>F.row(tenAndMore(4)),key:["Say: The box holds one full set of hearts and the rest are loose. How many hearts are in the box? (10)","Say: Now count them all. How many hearts in all? (14. Starting at ten and counting on 11, 12, 13, 14 is the goal. Counting every heart from 1 still counts, but write that down.)","Say: So 14 is ten and how many more? (4. Saying 10 and 4, or ten ones and four ones, all count.)","Say: Try one with no picture. 18 is ten and how many more? (8)"]}]},{id:17,title:"Longer, Shorter, Taller",short:"Compare",parts:[{std:["K.MD.A.2"],n:3,dur:60,dir:"Look at the picture. Answer out loud.",desc:"comparing two objects directly by length and by height, and describing the difference",fig:()=>F.row(comparePairs()),key:["Point to the two ribbons. Say: Both ribbons start at the same line. Which one is longer, A or B? (A)","Say: Now tell me about B. (B is shorter than A, or B is the short one. Look for a comparing word, not only pointing.)","Point to the two sunflowers. Say: These two grew in the same row. Which one is taller, C or D? Tell me about the other one too. (C is taller. D is shorter.)","The ribbons start at the same edge and the sunflowers stand on the same line, so the student can compare the far ends without measuring."]}]},{id:18,title:"Sort the Garden Tray",short:"Sort",parts:[{std:["K.MD.B.3"],n:3,dur:65,dir:"Look at the tray. Answer out loud.",desc:"sorting objects into categories, counting each category, and ordering the categories by count",fig:()=>F.row(mixTray()),key:["Say: Somebody tipped the garden tray out. Put these into groups by what they are. How many groups? (3: paper hearts, leaves, and sprouts.)","Say: Count each group. How many in each? (6 hearts, 4 leaves, 3 sprouts. 13 things in all.)","Say: Now put the three groups in order, from the group with the most down to the group with the fewest. (hearts, leaves, sprouts. That is 6, then 4, then 3.) Count it correct only when all three are in the right order.","If the student sorts by color instead of by what the things are, say: Now sort them by what they are, and note that the category had to be given."]}]},{id:19,title:"Garden Shapes",short:"Shapes",parts:[{title:"Shapes and Where They Are",std:["K.G.A.1"],n:3,dur:60,dir:"Look at the shed. Answer out loud.",desc:"naming shapes of things in a picture and telling where they are with position words",fig:()=>F.row(shapeShedFig()),key:["Say: The shed is drawn as two shapes. What shape is the wall? What shape is the roof? (a square wall and a triangle roof)","Say: Is the roof above the wall or below the wall? (above)","Say: What shape is the stepping stone, and where is it? (a circle, beside the shed, or next to the shed, or to the right of the shed. The bench is a rectangle and it is beside the stone.)","Both halves count here: the shape name and the position word. If the student names shapes but only points for the position, ask once: Can you tell me with words?"]},{title:"Flat or Solid",std:["K.G.A.3"],n:3,dur:55,dir:"Look at the six things. Answer out loud.",desc:"telling flat two-dimensional shapes apart from solid three-dimensional ones",fig:()=>F.row(flatSolidFig()),key:["Say first: Some shapes are flat, like a shape drawn on paper. Some are solid, like something you can pick up and hold. Then ask: Which numbers are flat? (1, 3, and 5)","Ask: Which numbers are solid? (2, 4, and 6)","Ask: Is a paper heart flat or solid? Is a ball flat or solid? (A paper heart is flat. A ball is solid.)","Naming the solids is a bonus here, not the check. Words like round, ball, box and can are fine."]}]},{id:20,title:"What Living Things Need",short:"Living Things",parts:[{std:["K-LS1-1"],n:3,dur:75,dir:"Look at both pictures. Answer out loud.",desc:"telling what a plant and an animal need to stay alive",html:()=>`<p class="big">Esme looks after a row of sunflowers in the shared garden. A duck lives on the garden pond.</p>
     <div class="figure">${ic("sunflower",96)}${ic("duck",96)}</div>`,qs:["Esme was away for a week and nobody watered her row. The sunflowers drooped right over. What were they missing?","The duck on the pond needs food too. Does a duck make its own food the way a plant does, or does it have to go and find food?","A neighbor watered Esme's row while she was away, and the sunflowers stood back up. Why did watering help them?"],key:["water","It has to go and find food. A plant makes its own food out in the light, and an animal cannot.","Because a plant needs water to stay alive, and it had not been getting any. Any answer that names water as something the plant needs counts."]}]},{id:21,title:"Weather for the Garden Club",short:"Weather",parts:[{std:["K-ESS2-1"],n:3,dur:75,dir:"Look at the week on the chart. Count out loud.",desc:"describing a weather pattern from a week of observations and using it",html:()=>`<p class="big">The garden club writes down the weather every morning. Here is one week.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th style="text-align:center">Mon</th><th style="text-align:center">Tue</th><th style="text-align:center">Wed</th><th style="text-align:center">Thu</th><th style="text-align:center">Fri</th><th style="text-align:center">Sat</th></tr>
     <tr><td>${ic("rain",58)}</td><td>${ic("sun",58)}</td><td>${ic("sun",58)}</td><td>${ic("rain",58)}</td><td>${ic("sun",58)}</td><td>${ic("sun",58)}</td></tr></table>`,qs:["Count the days it rained. How many?","Count the days it did not rain. How many?","The club waters the rows only on the days with no rain. So how many days did somebody water this week?"],key:["2","4","4. The same 4 days with no rain are the watering days, so the student has to use the count and not start over. If the student recounts and still says 4, that is fine."]},{std:["K-ESS2-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling how a living thing changes its surroundings",html:()=>`<p class="big">Last fall a squirrel buried acorns in the empty corner of the garden.</p>
     <div class="figure">${ic("squirrel",88)}${ic("acorn",88)}</div>`,qs:["This spring a small oak is growing up in that corner. Did the squirrel change that corner of the garden, or did the corner change the squirrel?","Tell me one way you could change a corner of a yard to make it a kinder place for birds."],key:["The squirrel changed the corner. It put acorns in the ground, and a tree grew where there was nothing before.","Any sensible answer about changing a space on purpose: set out a dish of water, hang a bird house, plant a flower, leave seeds out, pile up a few branches, keep away and stay quiet."]}]},{id:22,title:"Homes, Forecasts and the Pond",short:"Homes",parts:[{std:["K-ESS3-1"],n:3,dur:75,dir:"Match each animal to the place it lives. Answer out loud.",desc:"matching animals to the places that give them what they need",html:()=>`<p class="big">Three small animals live here. It is the shared garden. Each one lives in one place. It gets what it needs.</p>
     <div class="figure">${ic("bee",80)}${ic("snail",80)}${ic("bluebird",80)}</div>
     <p class="big">Here are the places. A hive. Under a cool damp leaf. The bird house on the shed.</p>`,qs:["Where does the bee live?","Where does the snail stay in the heat of the day?","Where does the bird build its nest?"],key:["a hive. Accept a nest of bees.","under a cool damp leaf. Accept somewhere damp and shady.","the bird house on the shed"]},{std:["K-ESS3-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling what a weather forecast is for and how people use one to get ready",html:()=>`<p class="big">Tomorrow the club is giving away its extra seedlings at a table by the gate. Tonight they read the forecast.</p>
     <div class="figure">${ic("cloud",88)}${ic("sprout",88)}</div>`,qs:["The forecast says heavy rain all day tomorrow. Should the club move the giveaway table in under the shed roof, or leave it standing out in the open?","A forecast tells what the weather will probably do next. Why is that helpful to somebody with a garden?"],key:["move the table in under the shed roof. Knowing beforehand is the whole use of a forecast.","Any sensible answer: they can cover the young plants, skip the watering, pick the beans before the rain, bring the tools in, pick a better day."]},{std:["K-ESS3-3"],n:2,dur:60,dir:"Answer out loud.",desc:"telling one way people can take better care of the land and water",html:()=>`<p class="big">There is a small pond at the end of the garden with frogs and ducks in it.</p>
     <div class="figure">${ic("frog",96)}${ic("wateringCan",96)}</div>`,qs:["Two gardeners scrub out their dirty pots with soap. One tips the soapy water straight into the pond. One tips it out on the gravel path. Which choice is better for the pond and the animals living in it?","The club wants to use less water this summer. Tell me one way they could."],key:["tipping it out on the gravel path. Soap in the pond would reach the frogs and the ducks.","Any sensible answer: catch rain in a barrel, water early in the morning so less dries away, water the roots and not the leaves, put straw or leaves on the soil to hold the water in, use a can instead of leaving a hose running."]}]},{id:23,title:"Pushes and Pulls in the Garden",short:"Push and Pull",parts:[{std:["K-PS2-1"],n:3,dur:75,dir:"Answer out loud. Do not say push or pull for the student.",desc:"telling a push from a pull, and comparing a strong pull with a gentle one",html:()=>`<p class="big">A push moves something away from you. A pull brings it along with you.</p>
     <div class="figure">${ic("box",88)}${ic("wateringCan",88)}</div>`,qs:["Rafi leans on the garden gate and sends it away from him to open it. Is that a push or a pull?","Esme takes the handle of the cart full of pots and brings it along behind her. Is that a push or a pull?","The cart is heavy. Esme gives the handle a gentle tug and the cart hardly moves. Then she tugs much harder. What is different?"],key:["a push","a pull","The cart moves, and it moves faster and farther. A stronger pull moves a thing more."]},{std:["K-PS2-2"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"deciding from test results whether a change worked, and telling a change of direction from a change of speed",html:()=>`<p class="big">Rafi set a hoop flat on the grass and tried to roll a ball into it. He tried each kind of roll 5 times and counted how often the ball got there.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th>Kind of roll</th><th style="text-align:center">Times out of 5 the ball reached the hoop</th></tr>
     <tr><td>a soft tap</td><td>1</td></tr><tr><td>a firm roll</td><td>5</td></tr></table>`,qs:["Which kind of roll got the ball to the hoop more often, and how many times out of 5?","The next ball is rolling straight past the hoop. Rafi puts his foot out on the far side, and the ball turns and goes into the hoop. Did his foot change the ball's direction, its speed, or both?"],key:["the firm roll, 5 times out of 5. The soft tap only got there 1 time out of 5.","its direction. Accept both if the student explains that it also slowed the ball down. Direction on its own is the answer to listen for."]}]},{id:24,title:"Sun and Shade in the Garden",short:"Sun",parts:[{std:["K-PS3-1"],n:2,dur:60,dir:"Answer out loud. If you can, feel a sunny spot and a shady spot together first.",desc:"telling what sunlight does to a surface it shines on",html:()=>`<p class="big">Two full watering cans stood out all morning. One sat in the open sunlight by the rows. One sat inside the shed.</p>
     <div class="figure">${ic("wateringCan",88)}${ic("sun",88)}</div>`,qs:["Which can has warm water in it now, the one in the open sunlight or the one in the shed?","The stone bench out in the sun is warm to sit on. The stone bench under the oak is cool. The two benches are exactly the same. What made the difference?"],key:["the can that sat in the open sunlight","the sunlight. One bench had sunlight on it all morning and the other was in the shade of the tree."]},{std:["K-PS3-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"designing and drawing a cover that keeps a spot out of the sunlight",html:()=>`<p class="big">The giveaway table is here. It is by the gate. It stands out in the open. The little seedlings sit on it. By the afternoon they are dry. They have dried right out. Draw something that keeps the sunlight off the table, like a cloth stretched over poles, a wide umbrella, or a lattice with a vine growing over it.</p>
     <div class="figure">${ic("sprout",88)}${ic("umbrella",88)}</div>`,qs:["Draw your sun cover over the giveaway table.","Point to where the sunlight is coming from and tell me how your cover keeps the seedlings cooler."],key:["Any cover drawn ABOVE or OVER the table. The three examples are in the direction, so copying one still counts. A cover drawn only beside the table is partial: ask where the sunlight is coming from.","Something like: it blocks the sun, the sun cannot reach them, it puts the table in a shadow."]}]},{id:25,title:"Solving a Problem at the Gate",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Listen, then answer out loud.",desc:"naming a problem people want to fix and asking a question about it",read:"When a row grows more beans than one family could eat, the extra beans go into an open basket by the gate, so any neighbor who wants some can take them. The basket is light and it has no lid. Nearly every day the wind tips it over, or the birds hop in and knock it off the post, and the beans end up in the dirt where nobody wants to pick them up.",qs:["What is the problem? The beans keep spilling out of the basket, or the beans are green?","Ask me one question about the basket that would help you fix this."],key:["The beans keep spilling out of the basket and into the dirt.","Any real question: how heavy is the basket, how hard does the wind blow there, how high is the post, could it have a lid, how many beans go in, do the birds come every day. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"drawing something whose shape would solve the problem",html:()=>`<p class="big">Draw something that would keep the beans in, like a box with a lid, a heavier tub set low on the ground, or a cover with a weight on top of it.</p>
     <div class="figure">${ic("box",88)}${ic("leaf",88)}</div>`,qs:["Draw your fix.","Tell me what you drew and how its shape keeps the beans in."],key:["Anything that would stop a tip or a spill: a lid, a heavy tub, a deep box, a low wide base, a cover held down with a stone, a strap. The three examples are in the direction, so copying one earns credit.","Naming it is what shows intent. Something like: the lid shuts the birds out, the heavy tub does not tip, the deep box holds them in."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"comparing test results from two fixes for the same problem",html:()=>`<p class="big">The club put 20 beans out each day, tried two fixes, and counted the beans still in the container at the end of the day.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th>Fix</th><th style="text-align:center">Beans still in it at the end of the day</th></tr>
     <tr><td>a heavy box with a lid</td><td>20</td></tr><tr><td>a cloth laid loose over the top</td><td>12</td></tr></table>`,qs:["Which fix worked better?","How do you know?"],key:["the heavy box with a lid","Because all 20 beans were still there in the box and only 12 were left under the cloth. The reason has to come from the chart, not from liking boxes."]}]},{id:26,title:"Rules and Doing Right",short:"Rules",parts:[{std:["HSS-K.1"],n:3,dur:75,dir:"Listen, then answer out loud.",desc:"following rules, knowing what happens when they are broken, and naming an honest choice",read:"Rafi borrowed the small trowel from the garden shed and dropped it in the tall grass somewhere on the way home. The next morning there was an empty hook on the tool board. Rafi could have said nothing at all. Instead he went to the garden club and said, I borrowed the trowel and I lost it in the grass. Saying it out loud was hard. His face felt hot and his voice went small, and he said it anyway. Two neighbors walked out to the grass with him, and the three of them found it together.",qs:["What did Rafi choose to do? Say that he lost the trowel, or say nothing and let everybody wonder?","One rule at the shed is a tool goes back clean. What might go wrong if nobody followed that rule?","Saying it out loud was hard for Rafi, and he said it anyway. What do we call it when somebody does the right thing even though it is hard?"],key:["He said that he had borrowed it and lost it.","The next person gets a dirty or a broken tool, the tools rust, dirt gets everywhere, somebody has to clean up after everybody else. Any real consequence counts.","Courage. Accept being brave, or being brave even when it is scary. The idea matters more than the word at this age. (HSS-K.1)"]}]},{id:27,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-K.4"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"reading map colors, telling land from water, using position words, and naming shared places",html:()=>`<p class="big">Here is a map. It shows the shared garden. The blue circle is the pond. The brown strips are the rows. They are garden rows. The green is the grass. The shed is behind the rows. It is drawn there. The gate is drawn in front.</p>
     <div class="figure"><svg viewBox="0 0 300 180" width="300" height="180" role="img" aria-label="A map showing water around an island with a house and a tree"><rect x="2" y="2" width="296" height="176" rx="14" fill="#BFE3F5" stroke="#6B4A3C" stroke-width="3"/><g stroke="#5E8FA8" stroke-width="3" stroke-linecap="round" fill="none"><path d="M22 34 q10 -8 20 0 t20 0"/><path d="M232 34 q10 -8 20 0 t20 0"/><path d="M22 150 q10 -8 20 0 t20 0"/><path d="M232 150 q10 -8 20 0 t20 0"/><path d="M22 92 q10 -8 20 0 t20 0"/><path d="M232 92 q10 -8 20 0 t20 0"/></g><ellipse cx="150" cy="90" rx="92" ry="54" fill="#A8D49A" stroke="#6B4A3C" stroke-width="3"/><g transform="translate(110,92)"><rect x="-20" y="-6" width="40" height="32" rx="4" fill="#F2E3C6" stroke="#6B4A3C" stroke-width="3"/><path d="M-26 -6 L0 -28 L26 -6 Z" fill="#D9704F" stroke="#6B4A3C" stroke-width="3" stroke-linejoin="round"/><rect x="-7" y="8" width="14" height="18" rx="2" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.4"/></g><g transform="translate(192,92)"><rect x="-6" y="2" width="12" height="24" rx="3" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.6"/><circle cx="0" cy="-8" r="22" fill="#6FB762" stroke="#6B4A3C" stroke-width="3"/></g></svg></div>
     <p class="big">${ic("cabin",56)} the shed &nbsp;&nbsp; ${ic("sprout",56)} the rows &nbsp;&nbsp; ${ic("drop",56)} the pond</p>`,qs:["On this map, which part is the water?","On a map the colors stand for things. What does the green stand for here?","The shed and the gate are on opposite sides of the rows. Which one is in front of the rows?","Name two places in your neighborhood where people share something, the way the garden is shared."],key:["the blue circle, which is the pond","the grass, which is land you can walk on. Accept the lawn or the ground.","the gate. The shed is behind the rows.","Any two real shared places: a park, a library, a playground, a pool, a bus, a sidewalk, a community garden. The moon does not count."]}]},{id:28,title:"Our Flag and Long Ago",short:"Long Ago",parts:[{std:["HSS-K.2"],n:2,dur:60,dir:"Look at the flag. Answer out loud.",desc:"recognizing the flag as a symbol of the country",html:()=>`<div class="figure">${ic("flag",120)}</div>`,qs:["This is our country's flag. Are the little shapes up in the corner stars or hearts?","A flag is a symbol, and that means it stands for something bigger than itself. What does our flag stand for?"],key:["star","our country. Accept the United States, America, or all the people who live here. If the student only says a flag, ask once: what does it stand for?"]},{std:["HSS-K.6"],n:3,dur:75,dir:"Answer out loud.",desc:"telling how life long ago was different from life today, and what a commemorative holiday is for",html:()=>`<p class="big">Long ago there were no washing machines.</p>
     <div class="figure">${ic("drop",96)}${ic("box",96)}</div>`,qs:["Long ago, how did a family get the clothes clean, by hand in a tub of water, or in a machine?","How do the clothes get washed at your house today?","Independence Day is a holiday the whole country shares every year. Name one thing people do together on a day like that."],key:["by hand in a tub of water","Any real answer: a washing machine, at a laundry place, somebody puts them in a machine, by hand sometimes. Naming today's way is the then-and-now half of this standard.","Any reasonable answer: a parade, music, flying a flag, a gathering, eating together, a day off school. The point to listen for is that a holiday is something people mark together, not an ordinary day."]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Sentence Parts",std:["RF.1.1"],needs:["RF.K.1"],n:3,dir:"Look at the sentence. Answer out loud.",html:()=>`<p class="passage" style="font-size:2.4rem;text-align:center;margin:0 auto;width:fit-content">Can you help me?</p><ol class="qlist"><li>Which word is the first word of the sentence?</li><li>Why does that word start with a big letter?</li><li>What mark is at the end of the sentence?</li></ol>`,key:["Can","Because it is the first word of the sentence. Sentences start with a capital letter.","A question mark. It tells you the sentence is asking something."]},2:{id:"L2",lv:true,title:"Level Up: Count to 120",std:["1.NBT.A.1"],needs:["K.CC.A.1"],n:2,dir:"Count out loud. Then read the numbers.",html:()=>`<ol class="qlist"><li>Start at 96. Count out loud to 107.</li><li>Read each number.</li></ol>${wordGrid(["58","102","119"])}`,key:["96, 97, 98, 99, 100, 101, 102, 103, 104, 105, 106, 107 with no skips. Listen at 99 to 100.","Reads fifty-eight, one hundred two, one hundred nineteen"]},4:{id:"L4",lv:true,title:"Level Up: Read a Story",std:["RL.1.1"],needs:["RL.K.1"],n:2,dir:"Read the story out loud. Then answer out loud.",html:()=>`<p class="passage" style="font-size:2rem;line-height:1.8">Rosa saw that the big watering can was too heavy for her neighbor. She ran over and took the other handle. Together they carried it all the way down the row, and not one drop spilled.</p><ol class="qlist"><li>What did Rosa take hold of?</li><li>What happened after Rosa and her neighbor carried the can down the row?</li></ol>`,key:["The other handle of the watering can","Not one drop spilled"]},5:{id:"L5",lv:true,title:"Level Up: Bigger Problems",std:["1.OA.A.1"],needs:["K.OA.A.2"],n:3,dir:"Solve on your paper. Say your answer out loud.",html:()=>`<ol class="qlist"><li>The club made 14 cards of thanks. They gave 6 of them away. How many are left?</li><li>Dev picked 8 beans and Ines picked 9 beans. How many beans in all?</li><li>Some hearts were in the jar. Then 5 more went in. Now there are 13. How many were in the jar at the start?</li></ol>`,key:["8 cards (14 - 6 = 8)","17 beans (8 + 9 = 17)","8 hearts. A box plus 5 equals 13, or 13 - 5 equals 8"]},7:{id:"L7",lv:true,title:"Level Up: Tricky Words",std:["RF.1.3"],needs:["RF.K.3"],n:3,dir:"Read each word out loud.",html:()=>wordGrid(["chop","when","vine"]),key:["Reads the first word (ch digraph, short o)","Reads the second word (wh digraph, short e)","Reads the third word (final e, long i)"]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=40;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}const STARTERS={opinion:["I would pick ____.","I like it because ____.","That is why I would pick it."],facts:["This is a ____.","It is ____.","One true thing is ____."],story:["One day somebody ____.","First, ____.","Then, ____.","I felt ____."]};function sentHtml(st){const wk=st&&st.parts&&st.parts[0]&&st.parts[0].wk||"facts";return`<ul class="starters">${(STARTERS[wk]||STARTERS.facts).map(x=>`<li>${x}</li>`).join("")}</ul>`}function tpsCmpHtml(){const bar=(y,w,fill,lab2)=>`<rect x="46" y="${y}" width="${w}" height="26" rx="7" fill="${fill}" stroke="var(--fig-ink)" stroke-width="2.5"/><text x="${54+w}" y="${y+14}" font-size="17" dominant-baseline="central" fill="var(--ink)">${lab2}</text>`;const svg=`<svg viewBox="0 0 370 128" width="350" style="max-width:100%" role="img" aria-label="Two bars that both start at the same line. The top bar is longer and the bottom bar is shorter."><line x1="46" y1="14" x2="46" y2="110" stroke="var(--fig-ink)" stroke-width="3" stroke-dasharray="6 5"/>${bar(28,196,"var(--gold)","longer")}${bar(74,112,"var(--gold)","shorter")}<text x="46" y="124" font-size="14" text-anchor="middle" fill="var(--muted)">start</text></svg>`;return`<div class="figure">${svg}</div>`+F.table(["Word","What it means"],[["longer","it goes past the other one"],["shorter","it stops before the other one"],["taller","it goes higher than the other one"],["the same","they both end in the same place"]])+`<p class="small">Line both things up at the same start line. Then look at the other end to see which one goes further.</p>`}const tpsIco=(n,px)=>(F.icon||F.pic2)(n,px)||"";const TPS_ABC=[["a","apple","apple"],["b","bear","bear"],["c","cat","cat"],["d","dog","dog"],["e","egg","egg"],["f","fish","fish"],["g","goat","goat"],["h","hen","hen"],["i","island","island"],["j","jam",""],["k","key","key"],["l","leaf","leaf"],["m","moon","moon"],["n","nose","nose"],["o","octopus","octopus"],["p","pig","pig"],["q","queen",""],["r","rabbit","rabbit"],["s","sun","sun"],["t","tent","tent"],["u","umbrella","umbrella"],["v","van",""],["w","wave","wave"],["x","box, x at the end","box"],["y","yarn",""],["z","zip",""]];function tpsLetterHtml(){const cell=c=>`<div style="display:flex;flex-direction:column;align-items:center;gap:2px;min-width:70px;padding:6px 4px;border:2px solid var(--line);border-radius:10px"><b style="font-size:1.45rem;line-height:1">${c[0]} ${c[0].toUpperCase()}</b>${c[2]?tpsIco(c[2],30):""}<span style="font-size:.9rem;text-align:center">${c[1]}</span></div>`;return`<div class="tool-scroll"><div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center">${TPS_ABC.map(cell).join("")}</div></div><ul class="frames"><li>Point to a letter and ask for its sound, not its name.</li><li>Rhyme: two words that end with the same sounds, like cat and hat.</li><li>Word parts: clap once for each part you hear. Cam-per is two claps.</li><li>First sound: say only the sound at the start of the word.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who was there and where it was","First, ____."],["2. Next","what happened","Then, ____."],["3. Last","how it ended","Last, ____."]])+`<p class="small">Tell the three parts in that order. The card gives the order words, so the student supplies what happened.</p>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={np:{name:"Number line 0 to 20",std:["1.NBT.A.1","1.NBT.B.2","1.OA.A.1","K.CC.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:()=>window.TPNL20(),bind:(b,r)=>window.TPNL20Bind(b,r)},tf:{name:"Ten frames",std:["1.MD.C.4","1.NBT.B.2","1.OA.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},sent:{name:"Sentence starters",std:["W.K.1","W.K.2","W.K.3","W.K.8"],html:sentHtml},cmp:{name:"Longer and shorter card",std:["K.MD.A.2"],html:tpsCmpHtml},letters:{name:"Letter and sound card",std:["RF.K.1","RF.K.2","RF.K.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["SL.K.4","W.K.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.K.1","RI.K.1","RL.K.1","SL.K.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.K.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"np",std:["K.CC.A.1"],msg:"The number line shows the counting order, so counting done with it is supported, not independent."},{t:"np",std:["K.OA.A.2","1.OA.A.1"],msg:"If the student counted up or back along the number line, note that the answer came from a visual, not from knowing the combination."},{t:"tf",std:["K.OA.A.3"],msg:"The ten frame is a fine way to show a number broken into two parts. Note whether the student found the second way without you moving counters."},{t:"np",std:["K.CC.B.4"],msg:"The number line shows the counting order, so a count read off it is supported. The check here is that the last number said answers how many, so note whether the student had to count again to tell you."},{t:"tf",std:["K.CC.C.6"],msg:"If the two groups were matched on the ten frame, the student compared with a model you built. Note that the comparing was supported."},{t:"tf",std:["K.NBT.A.1"],msg:"A full ten frame and some extra counters show ten and some more for the student. Note whether the student named the parts without you filling the frame."},{t:"np",std:["K.MD.B.3"],msg:"If the groups were counted along the number line, the counts were supported. The sorting and the ordering are still the student's own."},{t:"sent",msg:"Sentence starters give the student the opening words, so count those checks as supported, not independent."},{t:"passage",std:["RF.K.4"],msg:"If the lines on the screen were read to the student, this part shows listening, not reading. Rate it only if the student read the lines."},{t:"scribe",std:["W.K.1","W.K.2","W.K.3"],msg:"Telling an adult what to write is allowed at this grade. Note it, and do not rate the printing from this stop."},{t:"cmp",std:["K.MD.A.2"],msg:"The card supplies the words longer, shorter and taller, so rate on whether the student picks the right one, not on producing the word."},{t:"letters",std:["RF.K.1","RF.K.3"],msg:"The letter and sound card shows a keyword and a picture for each letter, so a sound read off the card is supported, not known by heart."},{t:"letters",std:["RF.K.2"],msg:"RF.K.2 is listening only. If the card was open, note that the student had the rhyme and the clapping rule in front of them."},{t:"retell",std:["SL.K.4","W.K.3"],msg:"The card gives the order words first, then and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.K.1","RI.K.1","L.K.1","SL.K.2","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.K.4"],msg:"A read with the reading window open is not a clean fluency check. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:["RF.K.4"]}}});
